// GENERATED by bundle.cjs from palette.js + gradient.js. Do not edit.
// Read the collection's own colour tokens at runtime.
//
// A page or a figure may not carry a colour (AGENTS.md), and a canvas cannot
// read a CSS custom property. So the token is read from the computed style and
// handed to the shader as a uniform — the same discipline as `var(--tb-accent)`
// in CSS, one layer down.
//
// The tokens live on `body` (see assets/stylesheets/themes.css, sections 3-4):
// the bundle and the subject tint both resolve there, so `body` is the element
// to read. `data-theme` is on `html` and `data-md-color-scheme` is on `body`.

const TOKENS = [
  "paper",
  "ink",
  "ink-soft",
  "rule",
  "accent",
  "accent-light",
  "accent-dark",
  "link",
  "fig-warn",
  "fig-good",
  "fig-grid",
];

const FALLBACK = {
  paper: "#faf9f5",
  ink: "#1f1e1b",
  "ink-soft": "#5c5a54",
  rule: "#e6e3da",
  accent: "#2f6690",
  "accent-light": "#4a7fae",
  "accent-dark": "#24506f",
  link: "#23577d",
  "fig-warn": "#a3402f",
  "fig-good": "#2c744a",
  "fig-grid": "#85837d",
};

let scratch = null;

/** Any CSS colour -> [r, g, b] in 0..1, via a 1x1 2D canvas. */
function toRgb(color, fallback = [0, 0, 0]) {
  if (!scratch) {
    scratch = document.createElement("canvas");
    scratch.width = 1;
    scratch.height = 1;
  }
  const ctx = scratch.getContext("2d", { willReadFrequently: true });
  if (!ctx) return fallback;
  ctx.fillStyle = "#010203"; // in case `color` is not a valid CSS colour
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, 1, 1);
  const d = ctx.getImageData(0, 0, 1, 1).data;
  return [d[0] / 255, d[1] / 255, d[2] / 255];
}

/** The tokens as strings, straight from the cascade. */
function readPalette(root = document.body || document.documentElement) {
  const cs = getComputedStyle(root);
  const out = {};
  for (const name of TOKENS) {
    out[name] = cs.getPropertyValue(`--tb-${name}`).trim() || FALLBACK[name];
  }
  return out;
}

/** The tokens as linear-ish RGB triples for a shader. */
function readPaletteRgb(root) {
  const tokens = readPalette(root);
  const out = { tokens };
  for (const name of TOKENS) out[camel(name)] = toRgb(tokens[name], toRgb(FALLBACK[name]));
  return out;
}

function camel(name) {
  return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

/**
 * Call `cb` whenever the reader changes bundle or scheme.
 *
 * The pipeline sets `data-theme` on `html` and `data-md-color-scheme` on `body`
 * before first paint, and the Settings runtime rewrites both. Nothing else
 * signals the change, so the two attributes are the observable.
 */
function watchPalette(cb) {
  let queued = false;
  const fire = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => {
      queued = false;
      cb(readPaletteRgb());
    });
  };
  const observer = new MutationObserver(fire);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  if (document.body) {
    observer.observe(document.body, { attributes: true, attributeFilter: ["data-md-color-scheme"] });
  }
  return () => observer.disconnect();
}


// Prototype: the two CSS-only alternates, and nothing else.
//
// `gradient-static` adds one <style> and never runs again. `gradient-animated`
// animates `background-position` on a fixed layer. Both declare only `var(--tb-*)`
// tokens — no literal colour — so they follow every bundle and both schemes the
// way a page or a figure must.
//
// Style, not script, is the point: a CSS gradient costs zero main-thread time
// when it is idle, and the animated one is composited by the browser.

const CLASS = "tb-bg-gradient";

function ensureStyle(id, text) {
  let style = document.getElementById(id);
  if (!style) {
    style = document.createElement("style");
    style.id = id;
    document.head.appendChild(style);
  }
  style.textContent = text;
  return style;
}

const LAYER = `
.${CLASS} {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    radial-gradient(120% 90% at 15% 10%, color-mix(in oklab, var(--tb-accent) 22%, transparent), transparent 60%),
    radial-gradient(100% 80% at 85% 90%, color-mix(in oklab, var(--tb-fig-warn) 14%, transparent), transparent 55%),
    linear-gradient(160deg, var(--tb-paper), var(--tb-paper));
  background-size: 200% 200%, 200% 200%, 100% 100%;
  background-position: 0% 50%, 100% 50%, 0 0;
}
`;

const KEYFRAMES = `
@keyframes tb-bg-drift {
  0%   { background-position: 0% 50%, 100% 50%, 0 0; }
  50%  { background-position: 100% 50%, 0% 50%, 0 0; }
  100% { background-position: 0% 50%, 100% 50%, 0 0; }
}
.${CLASS} { animation: tb-bg-drift 36s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) {
  .${CLASS} { animation: none; }
}
`;

function addLayer() {
  const layer = document.createElement("div");
  layer.className = CLASS;
  layer.setAttribute("aria-hidden", "true");
  (document.body || document.documentElement).appendChild(layer);
  return layer;
}

function mountStatic() {
  ensureStyle("tb-bg-gradient-style", LAYER);
  const layer = addLayer();
  return {
    layer,
    stop() { layer.remove(); },
    palette() { return null; },
    stats() { return { running: false, static: true }; },
  };
}

function mountAnimated() {
  ensureStyle("tb-bg-gradient-style", LAYER + KEYFRAMES);
  const layer = addLayer();
  return {
    layer,
    stop() { layer.remove(); },
    palette() { return null; },
    stats() { return { running: !window.matchMedia("(prefers-reduced-motion: reduce)").matches, cssAnimated: true }; },
  };
}

// The composited alternate: the same gradient on an oversized layer moved with
// `transform`, which the compositor animates without repainting the page. It is
// the fair "CSS-only" comparison, because `background-position` is not a
// compositor property and repaints every frame.
const CLASS_T = "tb-bg-gradient-t";

const LAYER_T = `
.${CLASS_T} {
  position: fixed;
  left: -20%;
  top: -20%;
  width: 140%;
  height: 140%;
  z-index: -1;
  pointer-events: none;
  will-change: transform;
  background-image:
    radial-gradient(60% 60% at 30% 30%, color-mix(in oklab, var(--tb-accent) 22%, transparent), transparent 65%),
    radial-gradient(55% 55% at 70% 70%, color-mix(in oklab, var(--tb-fig-warn) 14%, transparent), transparent 60%);
}
`;

const KEYFRAMES_T = `
@keyframes tb-bg-slide {
  0%   { transform: translate3d(-4%, -3%, 0) scale(1); }
  50%  { transform: translate3d(4%, 3%, 0) scale(1.06); }
  100% { transform: translate3d(-4%, -3%, 0) scale(1); }
}
.${CLASS_T} { animation: tb-bg-slide 36s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .${CLASS_T} { animation: none; } }
`;

function mountTransform() {
  ensureStyle("tb-bg-gradient-t-style", LAYER_T + KEYFRAMES_T);
  const layer = document.createElement("div");
  layer.className = CLASS_T;
  layer.setAttribute("aria-hidden", "true");
  (document.body || document.documentElement).appendChild(layer);
  return {
    layer,
    stop() { layer.remove(); },
    palette() { return null; },
    stats() { return { running: !window.matchMedia("(prefers-reduced-motion: reduce)").matches, cssAnimated: true, composited: true }; },
  };
}

window.__bgBoot = function () {
  const handle = mountTransform(window.__bgOptions || {});
  window.__bgHandle = handle;
  window.__bgReady = true;
  return handle;
};
